<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { Download, FileText, Search } from 'lucide-vue-next';
import { api, time, minutes, today, type Employee } from '../api';
const employees = ref<Employee[]>([]), employeeId = ref(''), month = ref(today().slice(0, 7)), report = ref<any>(null), error = ref(''), busy = ref(false);
onMounted(async () => { try { employees.value = await api('/employees'); employeeId.value = employees.value[0]?.id ?? ''; } catch (e) { error.value = (e as Error).message; } });
async function load() { busy.value = true; error.value = ''; report.value = null; try { report.value = await api(`/reports/dtr?employeeId=${employeeId.value}&month=${month.value}`); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function download() { error.value = ''; try { const response = await fetch(`/api/reports/dtr.pdf?employeeId=${report.value.employee.id}&month=${report.value.month}`, { credentials: 'include' }); if (!response.ok) throw new Error('Could not export this time record. Please sign in again if your session expired.'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `DTR-${report.value.employee.employeeNo}-${report.value.month}.pdf`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (e) { error.value = (e as Error).message; } }
</script>
<template><section class="panel report-filter"><form @submit.prevent="load"><label>Employee<select v-model="employeeId" required><option disabled value="">Select an employee</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.lastName }}, {{ e.firstName }} · {{ e.employeeNo }}</option></select></label><label>Reporting month<input v-model="month" type="month" required /></label><button class="button primary" :disabled="busy || !employeeId"><Search :size="17" />{{ busy ? 'Preparing…' : 'Preview time record' }}</button></form></section><p v-if="error" class="alert error" role="alert">{{ error }}</p><section v-if="!report" class="panel empty-state report-empty"><FileText :size="38" /><h3>A clear record of the month</h3><p>Select an employee and month to preview attendance,<br>review incomplete days, and export a daily time record.</p><span class="badge neutral">Civil Service Form 48 layout</span></section><section v-else class="panel"><div class="panel-heading"><div><h2>{{ report.employee.firstName }} {{ report.employee.lastName }}</h2><p>{{ report.employee.employeeNo }} · {{ report.employee.department }} · {{ report.month }}</p></div><button class="button primary" @click="download"><Download :size="17" /> Download PDF</button></div><div class="report-totals"><div><span>Recorded work</span><strong>{{ minutes(report.totalWorkedMinutes) }}</strong></div><div><span>Late arrival</span><strong>{{ minutes(report.totalLateMinutes) }}</strong></div><div><span>Undertime on complete days</span><strong>{{ minutes(report.totalUndertimeMinutes) }}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Morning in</th><th>Morning out</th><th>Afternoon in</th><th>Afternoon out</th><th>Worked</th><th>Status</th></tr></thead><tbody><tr v-for="r in report.rows" :key="r.date"><td class="numeric">{{ r.date }}</td><td class="numeric">{{ time(r.amIn) }}</td><td class="numeric">{{ time(r.amOut) }}</td><td class="numeric">{{ time(r.pmIn) }}</td><td class="numeric">{{ time(r.pmOut) }}</td><td class="numeric">{{ r.workedMinutes ? minutes(r.workedMinutes) : '—' }}</td><td><span :class="['badge', r.status === 'Present' ? 'green' : r.status === 'Late' || r.status === 'Incomplete' ? 'orange' : 'neutral']">{{ r.status }}</span></td></tr></tbody></table></div></section><p class="page-note">Draft Form 48 layout. HR must review incomplete days, approved leave, holidays, overtime, and local timekeeping rules before certification. This release does not calculate payroll.</p></template>
